import sys,json; sys.path.insert(0,'/tmp/dbtest')
exec(open('/tmp/dbtest/e2e_full.py').read().split("# ---------- seed")[0])
CUST='44444444-4444-4444-4444-444444444444'
PROD=q1("select id from public.products where slug='epoxy-floor-kit'")
print('=== K2. Quotation flow with the real statuses')
QID=q1("select id from public.quotations order by created_at desc limit 1")
st=q1(f"select status from public.quotations where id='{QID}'"); print('  quotation status now:',st)
ok,e=call('authenticated',f"select public.transition_quotation_status('{QID}','quoted')",sub=OWNER); check("legacy status 'quoted' is refused by the database (so the screen must not offer it)", not ok, e)
# fresh quotation to walk the legal path
ok,q=call('anon',"select public.submit_quotation_request('Ann Mwende','ann@example.co.ke','0722000111','Nairobi','Office floor','Polished concrete','Office floor','500k-1M','Soon')")
Q2=q['quotation_id']
ok,e=call('authenticated',f"select public.transition_quotation_status('{Q2}','sent')",sub=OWNER); check('cannot send a quotation with no line items', not ok, e)
call('authenticated',f"select public.upsert_quotation_item_transaction('{Q2}',NULL,'Polished concrete',100,'sqm',1800,NULL)",sub=OWNER)
ok,r=call('authenticated',f"select public.transition_quotation_status('{Q2}','sent')",sub=OWNER); check('quotation sent to the customer', ok, r)
print('  sent-quotation notifications queued:',q1("select count(*) from public.communication_outbox where subject ilike '%quotation%' or message ilike '%quotation%'"))
print('=== L2. Customer notification preferences')
run(f"update auth.users set email_confirmed_at=now() where id='{CUST}'")
ok,r=call('authenticated',"select public.claim_customer_portal_access()",sub=CUST); print('  claim ->',str(r)[:100])
ok,r=call('authenticated',"select public.update_customer_notification_preferences(p_email_enabled := true, p_sms_enabled := false, p_whatsapp_enabled := false, p_marketing_email_enabled := false, p_marketing_sms_enabled := false)",sub=CUST)
check('customer saves preferences with the p_-prefixed names the app now sends', ok, r); print('  ->',str(r)[:240])
print('=== M2. Procurement')
ok,s=call('authenticated',"select public.create_supplier('Acme Tiles Ltd','Mary','mary@acme.test','0733444555','Industrial Area',NULL)",sub=OWNER); print('  supplier ->',str(s)[:160])
SUP=q1("select id from public.suppliers order by created_at desc limit 1")
run("insert into public.warehouses(name) values ('Main Warehouse') on conflict do nothing"); WH=q1("select id from public.warehouses limit 1")
ok,po=call('authenticated',f"select public.create_purchase_order('{SUP}','{WH}',NULL,NULL)",sub=OWNER); print('  po ->',str(po)[:200])
POID=q1("select id from public.purchase_orders order by created_at desc limit 1")
ok,e=call('authenticated',f"select public.transition_purchase_order_lifecycle('{POID}','sent')",sub=OWNER); check('empty purchase order cannot be sent', not ok, e)
ok,it=call('authenticated',f"select public.add_purchase_order_item('{POID}','{PROD}','Epoxy kits',10,1500)",sub=OWNER); check('line added', ok, it)
ok,e=call('authenticated',f"select public.transition_purchase_order_lifecycle('{POID}','ordered')",sub=OWNER); check('draft cannot jump straight to ordered', not ok, e)
ok,r=call('authenticated',f"select public.transition_purchase_order_lifecycle('{POID}','sent')",sub=OWNER); check('draft -> sent', ok, r)
ok,r=call('authenticated',f"select public.transition_purchase_order_lifecycle('{POID}','ordered')",sub=OWNER); check('sent -> ordered', ok, r)
ITEM=q1(f"select id from public.purchase_order_items where purchase_order_id='{POID}'")
s0=int(q1("select stock_quantity from public.products where slug='epoxy-floor-kit'"))
ok,r=call('authenticated',f"select public.receive_purchase_order_item('{ITEM}',4)",sub=OWNER); check('receive 4 of 10', ok, r)
s1=int(q1("select stock_quantity from public.products where slug='epoxy-floor-kit'")); check('stock increased by 4', s1==s0+4, f'{s0}->{s1}')
check('PO is partial', q1(f"select status from public.purchase_orders where id='{POID}'")=='partial', q1(f"select status from public.purchase_orders where id='{POID}'"))
ok,e=call('authenticated',f"select public.receive_purchase_order_item('{ITEM}',20)",sub=OWNER); check('cannot receive more than ordered', not ok, e)
ok,r=call('authenticated',f"select public.receive_purchase_order_item('{ITEM}',6)",sub=OWNER); check('receive the remaining 6', ok, r)
check('PO is received', q1(f"select status from public.purchase_orders where id='{POID}'")=='received', q1(f"select status from public.purchase_orders where id='{POID}'"))
check('stock is start + 10', int(q1("select stock_quantity from public.products where slug='epoxy-floor-kit'"))==s0+10)
print(f"\n{sum(1 for _,c in results if c)}/{len(results)} checks passed")
